<?php
namespace App\Http\Controllers\Public;
use App\Actions\Rental\CreateRentalBooking;use App\Http\Controllers\Controller;use App\Http\Controllers\Public\Concerns\HandlesCatalogInteractions;use App\Http\Requests\Consumer\CreateRentalBookingRequest;use App\Models\CatalogEntity;use App\Models\FeatureFlag;use App\Models\RentalRate;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class RentalController extends Controller
{use HandlesCatalogInteractions;private function enabled():void{abort_unless(FeatureFlag::where('key_name','public-rental')->where('status','enabled')->exists(),404);}public function index(Request $r):View{$this->enabled();$items=CatalogEntity::publicDomain('rental')->with(['rentalVehicle.rates.offer','media','location','region','category','mitra'])->when($r->q,fn($q,$v)=>$q->where('name','like','%'.$v.'%'))->when($r->type,fn($q,$v)=>$q->whereHas('rentalVehicle',fn($x)=>$x->where('vehicle_type',$v)))->when($r->drive_mode==='self_drive',fn($q)=>$q->whereHas('rentalVehicle',fn($x)=>$x->where('self_drive_available',true)))->paginate(12)->withQueryString();return view('public.catalog-domain.index',['items'=>$items,'title'=>'Rental','routePrefix'=>'rental']);}public function show(string $slug):View{$this->enabled();$item=CatalogEntity::publicDomain('rental')->where('slug',$slug)->with(['rentalVehicle.rates.offer','rentalVehicle.availability','media','reviews'=>fn($q)=>$q->where('status','published')->with(['user', 'replies.author', 'replies.mitra'])->latest()])->firstOrFail();return view('public.catalog-domain.show',['item'=>$item,'title'=>'Rental','routePrefix'=>'rental']);}public function favorite(Request $r,string $slug):RedirectResponse{return $this->toggleFavorite($r,CatalogEntity::publicDomain('rental')->where('slug',$slug)->firstOrFail(),true);}public function unfavorite(Request $r,string $slug):RedirectResponse{return $this->toggleFavorite($r,CatalogEntity::publicDomain('rental')->where('slug',$slug)->firstOrFail(),false);}public function review(Request $r,string $slug):RedirectResponse{return $this->storeReview($r,CatalogEntity::publicDomain('rental')->where('slug',$slug)->firstOrFail());}public function book(CreateRentalBookingRequest $r,string $slug,CreateRentalBooking $action):RedirectResponse{$entity=CatalogEntity::publicDomain('rental')->where('slug',$slug)->firstOrFail();$rate=RentalRate::findOrFail($r->validated('rental_rate_id'));$docs=collect($r->validated('document_ids',[]));abort_unless($docs->isEmpty()||$r->user()->renterDocuments()->whereIn('id',$docs)->count()===$docs->count(),403);$action->execute($entity->rentalVehicle,$rate,$r->user(),$r->validated());return back()->with('status','Permintaan booking dikirim.');}}
